package contract

import runar "github.com/icellan/runar/packages/runar-go"

type LtGo struct {
	runar.StatefulSmartContract
	Owner    runar.PubKey `runar:"readonly"`
	Deadline runar.Bigint `runar:"readonly"`
}

func (c *LtGo) Close(sig runar.Sig) {
	runar.Assert(runar.CheckSig(sig, c.Owner))
	runar.Assert(runar.ExtractLocktime(c.TxPreimage) >= c.Deadline)
	runar.Assert(runar.ExtractSequence(c.TxPreimage) != 0xffffffff)
}

