  count: bigint;

  constructor(h: bigint, count: bigint) {
    super(h, count);
    this.h = h;
    this.count = count;
  }

  public spend() {
    assert(extractSequence(this.txPreimage) !== 0xffffffffn);
    let lt = extractLocktime(this.txPreimage);
    if (this.h > 5n) {
      lt = currentBlockHeight();
    }
    assert(lt >= this.h);
    this.count = this.count + 1n;
  }
}

